int set_color_map(struct fb_cmap *cmap, struct fb_info *info) {
    if (info->var.bits_per_pixel <= 8) {
        if (cmap->start + cmap->len > 256)
            return -EINVAL;

        unsigned int *palette;
        palette = kmalloc(cmap->len * 3 * sizeof(unsigned int), GFP_KERNEL);
        if (!palette)
            return -ENOMEM;

        for (int i = 0; i < cmap->len; ++i) {
            unsigned int r = cmap->red[i] >> (8 - info->var.red.length);
            unsigned int g = cmap->green[i] >> (8 - info->var.green.length);
            unsigned int b = cmap->blue[i] >> (8 - info->var.blue.length);
            palette[i * 3] = r;
            palette[i * 3 + 1] = g;
            palette[i * 3 + 2] = b;
        }

        uvesafb_setpalette(cmap->start, cmap->len, palette, info);
        kfree(palette);
    } else {
        for (int i = 0; i < cmap->len; ++i) {
            int err = uvesafb_setcolreg(i + cmap->start, cmap->red[i],
                                        cmap->green[i], cmap->blue[i],
                                        cmap->transp[i], info);
            if (err)
                return err;
        }
    }

    return 0;
}

int uvesafb_set_cmap(struct fb_cmap *cmap, struct fb_info *info)
{
    int i;

    if (info->var.bits_per_pixel > 8) {
        for (i = 0; i < cmap->len; i++) {
            if (cmap->start + i > 255)
                return -EINVAL;
            uvesafb_setcolreg(i + cmap->start, cmap->red[i], cmap->green[i], cmap->blue[i], 0, info);
        }
        return 0;
    }

    if (cmap->start + cmap->len > 256)
        return -EINVAL;

    for (i = 0; i < cmap->len; i++) {
        unsigned char r = cmap->red[i];
        unsigned char g = cmap->green[i];
        unsigned char b = cmap->blue[i];

        if (info->var.red.length < 8)
            r >>= (8 - info->var.red.length);
        if (info->var.green.length < 8)
            g >>= (8 - info->var.green.length);
        if (info->var.blue.length < 8)
            b >>= (8 - info->var.blue.length);

        uvesafb_setcolreg(cmap->start + i, r, g, b, 0, info);
    }

    return 0;
}

int uvesafb_set_cmap(struct fb_cmap *cmap, struct fb_info *info) {
    int i;
    u16 *red = NULL, *green = NULL, *blue = NULL, *transp = NULL;

    if (info->var.bits_per_pixel > 8) {
        for (i = 0; i < cmap->len; i++) {
            uvesafb_setcolreg(cmap->start + i,
                              cmap->red[i], cmap->green[i], cmap->blue[i],
                              cmap->transp[i], info);
        }
        return 0;
    }

    red = kmalloc_array(cmap->len, sizeof(u16), GFP_KERNEL);
    if (!red)
        return -ENOMEM;
    green = kmalloc_array(cmap->len, sizeof(u16), GFP_KERNEL);
    if (!green) {
        kfree(red);
        return -ENOMEM;
    }
    blue = kmalloc_array(cmap->len, sizeof(u16), GFP_KERNEL);
    if (!blue) {
        kfree(red);
        kfree(green);
        return -ENOMEM;
    }
    transp = kmalloc_array(cmap->len, sizeof(u16), GFP_KERNEL);
    if (!transp) {
        kfree(red);
        kfree(green);
        kfree(blue);
        return -ENOMEM;
    }

    for (i = 0; i < cmap->len; i++) {
        red[i] = cmap->red[i] << (16 - info->dac_width);
        green[i] = cmap->green[i] << (16 - info->dac_width);
        blue[i] = cmap->blue[i] << (16 - info->dac_width);
        transp[i] = cmap->transp[i];
    }

    uvesafb_setpalette(cmap->start, cmap->len, red, green, blue, transp, info);

    kfree(red);
    kfree(green);
    kfree(blue);
    kfree(transp);

    return 0;
}

